            def rotate(self) -> None:
                self.dx, self.dy = (self.dy, -self.dx)

            def move(self) -> None:
                self.x += self.dx
                self.y += self.dy

            @property
            def get_x(self) -> int:
                return self.x

            @property
            def get_y(self) -> int:
                return self.y
        n = int(input())
