import io
import sys
from contextlib import redirect_stdout

def solve(text):
    def program():
        S = input()
        for i in range(len(S)):
            if 'A' < S[i] < 'Z':
                print(i + 1)
    previous = sys.stdin
    output = io.StringIO()
    try:
        with redirect_stdout(output):
            program()
    except SystemExit as status:
        if status.code not in (None, 0):
            raise
    finally:
        sys.stdin = previous
    return output.getvalue().strip()
```

