import sys
from contextlib import redirect_stdout

def solve(text):
    def program():
        def solve(h, w, m, t, a, x):
            a = [_ - 1 for _ in a]
            cnt = {color: 0 for color in x}
            S_row = set()
            S_col = set()
            for k in range(m - 1, -1, -1):
                if t[k] == 1:
                    if not a[k] in S_row:
                        S_row.add(a[k])
                        cnt[x[k]] += w - len(S_col)
                elif not a[k] in S_col:
                    S_col.add(a[k])
                    cnt[x[k]] += h - len(S_row)
            cnt[0] = h * w - sum(cnt.values())
            return {color: num for color, num in cnt.items() if num > 0}
        h, w, m = map(int, input().split())
        t, a, x = zip(*[map(int, input().split()) for i in range(m)])
        color_num_mapping = solve(h, w, m, t, a, x)
