def solve(text):
    def program():
        n, q = map(int, input().split())
        s = str(input())
        cnt = 0
        for i in range(q):
            t, x = map(int, input().split())
            if t == 1:
                cnt += 1
                cnt = cnt % n
            if t == 2:
                print(s[(n - cnt + (x - 1)) % n])
    previous = sys.stdin
    output = io.StringIO()
    try:
        sys.stdin = io.StringIO(text)
        with redirect_stdout(output):
            program()
    except SystemExit as status:
        if status.code not in (None, 0):
            raise
    finally:
        sys.stdin = previous
    return output.getvalue().strip()
